    if(argc==2&&std::string_view(argv[1])=="--help"){std::cout<<usage<<'\n';return 0;}const auto o=options(argc,argv);output=o.output;Guard model(o.data/"Model/EmperorBuildingModels.txt"),map(o.data/o.map);Context context(o.data,o.map);std::vector<Guard> inputs;Json events=Json::array(),manifest=Json::array();auto world=context.create();
