        while(world.ticks()<=o.ticks){while(at<recorded.size()&&recorded[at]["tick"].get<std::uint64_t>()==world.ticks()){const auto event=recorded[at++];const auto type=event.at("type").get<std::string>();if(type=="command")apply(decode(event.at("command")),event.at("reason").get_ref<const std::string&>().c_str());else if(type=="refusal")refuse(decode(event.at("command")),event.at("reason").get_ref<const std::string&>().c_str());else if(type=="checkpoint")capture(event.at("label").get_ref<const std::string&>().c_str());else throw std::runtime_error("Unsupported replay event");}if(world.ticks()==o.ticks)break;advance();}l::check(at==recorded.size()&&events==recorded,"Separate process did not replay every exact paid event");proof=plan.at("proof");
